content:
@import "tailwindcss";
@theme {
  --color-brand: #204f5f;
  --color-lime: #b1ca00;
  --font-sans: "Manrope Variable", sans-serif;
}
:root {
  /* Paleta de districo.com.uy (Elementor post-11.css y post-53.css) */
  --ink: #204f5f;
  --ink-deep: #163d4a;
  --lime: #b1ca00;
  --lime-text: #5f7300;
  --lime-soft: color-mix(in srgb, var(--lime) 18%, white);
  --text: #636466;
  --muted: #636466;
  --line: #dcdcdc;
  --paper: #efefef;
  --on-ink: #ffffff;
  --on-ink-muted: #c9d6da;
  --on-ink-line: rgb(255 255 255 / 0.14);
  --radius: 18px;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  color: var(--ink);
  background: white;
  font-family: "Manrope Variable", sans-serif;
  font-size: 14px;
  line-height: 1.65;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
button {
  cursor: pointer;
}
button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
input,
select,
textarea {
  max-width: 100%;
}
img {
  max-width: 100%;
  display: block;
}
h1,
h2,
h3,
p {
  margin: 0;
}
h1,
h2,
h3 {
  line-height: 1.2;
  letter-spacing: -0.045em;
}
h1 {
  font-size: clamp(30px, 4vw, 48px);
  font-weight: 650;
}
h2 {
  font-size: clamp(24px, 2.6vw, 34px);
  font-weight: 650;
}
h3 {
  font-size: 18px;
  font-weight: 650;
}
p + p {
  margin-top: 14px;
}
a,
button {
  transition:
    background 0.18s,
    color 0.18s,
    transform 0.18s;
}
a:hover {
  color: var(--lime-text);
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--lime-text);
  outline-offset: 4px;
}
::selection {
  background: var(--lime-soft);
}
svg {
  flex-shrink: 0;
}
.container {
  width: min(1280px, calc(100% - 80px));
  margin-inline: auto;
}
.section {
  padding-block: 64px;
}
.muted {
  color: var(--muted);
}
.eyebrow {
  text-transform: uppercase;
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.17em;
  margin-bottom: 14px;
}
.row,
.actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.between {
  justify-content: space-between;
}
.actions {
  margin-top: 24px;
}
.stack {
  display: grid;
  gap: 20px;
}
.button {
  min-height: 46px;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: var(--ink);
  color: white;
  padding: 12px 22px;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.4;
}
.button:hover {
  background: var(--ink-deep);
  color: white;
  transform: translateY(-1px);
}
.button.lime {
  background: var(--lime);
  color: var(--ink);
}
.button.secondary {
  background: transparent;
  border-color: var(--line);
  color: var(--ink);
}
.button.secondary:hover {
  background: var(--paper);
}
.button.small {
  padding: 8px 14px;
  min-height: 38px;
}
.button.danger {
  background: #9a3535;
}
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: transparent;
  border: 0;
  border-radius: 6px;
}
.icon-button:hover {
  background: var(--paper);
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 650;
  font-size: 13px;
}
.skip-link {
  position: fixed;
  left: 20px;
  top: -100px;
  background: var(--ink);
  color: white;
  padding: 12px;
  z-index: 100;
}
.skip-link:focus {
  top: 10px;
}
.demo-strip {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  background: var(--lime-soft);
  color: var(--ink);
  padding: 5px 16px;
  font-size: 10px;
  letter-spacing: 0.02em;
}
.demo-strip button {
  text-decoration: underline;
  min-height: 28px;
  border: 0;
  background: transparent;
}
.dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lime);
  margin-right: 6px;
}
.topbar {
  background: var(--ink);
  color: var(--on-ink-muted);
  font-size: 10px;
  padding: 7px 0;
  letter-spacing: 0.04em;
}
.topbar .container {
  display: flex;
  justify-content: space-between;
}
.topbar a {
  display: flex;
  gap: 8px;
  align-items: center;
}
.header {
  background: white;
  position: relative;
  z-index: 10;
}
.header-main {
  display: flex;
  align-items: center;
  gap: 50px;
  min-height: 96px;
}
.logo {
  flex-shrink: 0;
}
.logo img {
  width: 179px;
  height: auto;
}
.search {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 9px 13px;
  flex: 1;
  margin-inline: 20px;
  max-width: 580px;
}
.search:focus-within {
  outline: 3px solid var(--lime-text);
  outline-offset: 2px;
}
.search input {
  background: transparent;
  border: 0;
  outline: none;
  min-width: 0;
  width: 100%;
  font-size: 12px;
}
.search button {
  background: transparent;
  border: 0;
  display: flex;
  width: 30px;
  height: 30px;
  align-items: center;
  justify-content: center;
}
.header-actions {
  display: flex;
  gap: 28px;
  align-items: center;
  margin-left: auto;
}
.account-link {
  display: flex;
  gap: 12px;
  align-items: center;
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}
.account-link small {
  display: block;
  color: var(--muted);
  font-size: 10px;
  font-weight: 400;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cart-link {
  position: relative;
}
.cart-count {
  position: absolute;
  right: 0;
  top: 0;
  background: var(--lime);
  border-radius: 50%;
  font-size: 9px;
  width: 16px;
  height: 16px;
  color: var(--ink);
  text-align: center;
}
.navline {
  border-block: 1px solid var(--line);
}
.navline nav {
  display: flex;
  gap: 38px;
  align-items: center;
  height: 48px;
  font-size: 12px;
  font-weight: 600;
}
.navline .active,
.mobile-nav .active {
  color: var(--lime-text);
}
.be-client {
  margin-left: auto;
  display: flex;
  gap: 14px;
  align-items: center;
}
.mobile-menu {
  display: none;
}
.page-heading {
  margin-bottom: 32px;
}
.page-heading .muted {
  margin-top: 14px;
  max-width: 660px;
}
.breadcrumbs {
  font-size: 11px;
  color: var(--muted);
  margin-bottom: 28px;
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.needs {
  padding: 28px 0 32px;
}
.needs-intro {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 22px;
}
.needs-intro p {
  font-size: 11px;
  color: var(--muted);
}
.needs-intro strong {
  font-size: 12px;
}
.need-list {
  display: flex;
  justify-content: space-between;
  gap: 28px;
  overflow-x: auto;
  padding: 4px 3px 10px;
  scrollbar-width: thin;
}
.need {
  flex: 0 0 108px;
  text-align: center;
  font-size: 11px;
  font-weight: 650;
}
.need-circle {
  width: 88px;
  height: 88px;
  border-radius: 50%;
  border: 1px solid var(--line);
  margin: 0 auto 10px;
  background: var(--paper);
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    transform 0.2s,
    border-color 0.2s;
  overflow: hidden;
}
.need:nth-child(2n) .need-circle {
  background: var(--paper);
}
.need:nth-child(3n) .need-circle {
  background: var(--paper);
}
.need-circle img {
  height: 72px;
  width: 68px;
  object-fit: contain;
  mix-blend-mode: multiply;
}
.need:hover .need-circle {
  transform: translateY(-4px);
  border-color: var(--lime);
}
.hero {
  border-radius: var(--radius);
  background: var(--paper);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1.12fr;
  min-height: 430px;
  position: relative;
}
.hero-copy {
  padding: 55px 48px;
  position: relative;
  z-index: 1;
}
.hero h1 {
  font-size: clamp(36px, 4.6vw, 60px);
  line-height: 1.09;
  max-width: 520px;
  font-weight: 550;
}
.hero h1 em {
  font-style: normal;
  color: var(--lime-text);
}
.hero-copy > p:not(.eyebrow) {
  color: var(--text);
  max-width: 340px;
  font-size: 13px;
  margin-top: 20px;
}
.hero .actions {
  margin-top: 28px;
}
.hero-visual {
  position: relative;
  overflow: hidden;
  background: var(--paper);
}
.hero-visual picture,
.hero-visual img {
  height: 100%;
  width: 100%;
  object-fit: cover;
}
.hero-caption {
  position: absolute;
  bottom: 18px;
  right: 18px;
  border-radius: 8px;
  background: #fffffff0;
  padding: 13px 18px;
  font-size: 10px;
  box-shadow: 0 3px 30px #1526140c;
}
.hero-caption strong {
  display: block;
  font-size: 13px;
}
.benefits {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 25px 0;
  border-bottom: 1px solid var(--line);
  gap: 30px;
}
.benefits > div {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 14px;
  font-size: 11px;
}
.benefits strong {
  display: block;
  font-size: 12px;
}
.benefits svg {
  color: var(--lime-text);
}
.section-title {
  display: flex;
  justify-content: space-between;
  align-items: end;
  margin-bottom: 28px;
  gap: 20px;
}
.section-title .muted {
  font-size: 12px;
  margin-top: 10px;
}
.line-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.line-card {
  min-height: 265px;
  background: var(--paper);
  border-radius: 12px;
  padding: 28px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: start;
  justify-content: end;
}
.line-card h3 {
  font-size: 23px;
  position: relative;
  z-index: 1;
}
.line-card p {
  font-size: 12px;
  margin-top: 8px;
  position: relative;
  z-index: 1;
}
.line-card img {
  position: absolute;
  width: 150px;
  height: 170px;
  object-fit: contain;
  right: 6px;
  top: 8px;
  mix-blend-mode: multiply;
}
.line-card .round-arrow {
  position: absolute;
  right: 20px;
  bottom: 20px;
  background: white;
  border-radius: 50%;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
}
.line-card:nth-child(2) {
  background: var(--paper);
}
.line-card:nth-child(3) {
  background: var(--paper);
}
.brand-strip {
  background: var(--paper);
  padding: 40px 0;
}
.brand-list {
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
  justify-content: space-between;
  align-items: center;
}
.brand-word {
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -0.05em;
  color: var(--text);
}
.brand-word:hover {
  color: var(--ink);
}
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 24px;
}
.product-card {
  min-width: 0;
  position: relative;
  /* Columna flexible: el pie queda alineado aunque el nombre ocupe más líneas. */
  display: flex;
  flex-direction: column;
}
.product-image {
  background: var(--paper);
  aspect-ratio: 1/1.02;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.product-image img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  mix-blend-mode: multiply;
  transition: transform 0.25s;
}
.product-card:hover .product-image img {
  transform: scale(1.035);
}
.product-card .tag {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 9px;
  background: white;
  border-radius: 3px;
  padding: 3px 7px;
  z-index: 1;
}
.product-meta {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin-top: 15px;
}
.product-card h3 {
  font-size: 13px;
  line-height: 1.55;
  letter-spacing: -0.01em;
  margin-top: 5px;
  font-weight: 600;
  min-height: 42px;
  margin-bottom: 14px;
}
.product-bottom {
  border-top: 1px solid var(--line);
  margin-top: auto;
  padding-top: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 40px;
  font-size: 11px;
}
.product-bottom strong {
  font-size: 16px;
}
.product-bottom .icon-button {
  border: 1px solid var(--line);
  width: 32px;
  height: 32px;
}
.cta-band {
  background: var(--ink);
  color: white;
  border-radius: 14px;
  padding: 50px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  position: relative;
  overflow: hidden;
}
.cta-band p {
  color: var(--on-ink-muted);
  font-size: 13px;
  margin-top: 12px;
}
.cta-band h2 {
  max-width: 580px;
}
.cta-band .button {
  white-space: nowrap;
}
footer {
  background: #f4f6f2;
  border-top: 1px solid var(--line);
  padding-top: 55px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 0.8fr 1fr 1fr;
  gap: 36px;
  padding-bottom: 45px;
}
.footer-logo {
  width: 166px;
  height: auto;
  margin-bottom: 22px;
}
.footer-grid p {
  font-size: 11px;
  color: var(--muted);
  margin-block: 14px;
}
.footer-grid p svg {
  display: inline;
  vertical-align: middle;
}
.footer-grid h3 {
  font-size: 12px;
  letter-spacing: 0;
  margin-bottom: 18px;
}
.footer-grid a {
  font-size: 11px;
  display: block;
  margin-block: 9px;
}
.footer-pill {
  font-size: 9px;
  border: 1px solid var(--line);
  padding: 6px 10px;
  border-radius: 20px;
}
.footer-bottom {
  border-top: 1px solid var(--line);
  padding-block: 20px;
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted);
}
.catalog-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 40px;
}
.filters {
  padding-right: 24px;
  border-right: 1px solid var(--line);
}
.filter-section {
  padding: 20px 0;
  border-bottom: 1px solid var(--line);
}
.filter-section:first-child {
  padding-top: 0;
}
.filter-section h3 {
  font-size: 12px;
  letter-spacing: 0;
  margin-bottom: 12px;
}
.filter-option {
  display: flex;
  gap: 9px;
  align-items: center;
  margin: 9px 0;
  font-size: 12px;
  cursor: pointer;
}
.filter-option input {
  accent-color: var(--ink);
  width: 15px;
  height: 15px;
}
.catalog-layout .product-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}
.catalog-toolbar {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  margin-bottom: 25px;
  font-size: 12px;
}
.filter-trigger {
  display: none;
}
.active-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}
.chip {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 30px;
  padding: 6px 12px;
  font-size: 11px;
  background: white;
}
.pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  margin-top: 38px;
}
.detail-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 65px;
  align-items: start;
}
.detail-image {
  background: var(--paper);
  border-radius: 16px;
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 50px;
  overflow: hidden;
}
.detail-image img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  mix-blend-mode: multiply;
  transform-origin: var(--zoom-origin, 50% 50%);
  transition: transform 0.2s ease;
}
@media (hover: hover) and (pointer: fine) {
  .detail-image {
    cursor: zoom-in;
  }
  .detail-image:hover img {
    transform: scale(2);
  }
}
.thumbs {
  display: flex;
  gap: 10px;
  margin-top: 15px;
  overflow-x: auto;
}
.thumbs button {
  flex: none;
  width: 65px;
  height: 65px;
  border: 1px solid var(--line);
  padding: 6px;
  background: white;
  border-radius: 7px;
}
.thumbs button[aria-pressed="true"] {
  border-color: var(--ink);
}
.thumbs img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.detail-info h1 {
  font-size: 34px;
  margin-block: 12px 20px;
}
.detail-info .price {
  font-size: 30px;
  font-weight: 650;
  margin: 25px 0 8px;
}
.status-pill {
  display: inline-block;
  font-size: 10px;
  background: var(--lime-soft);
  color: var(--ink);
  padding: 4px 10px;
  border-radius: 30px;
}
.status-pill.pending {
  background: #fbefdb;
  color: #826013;
}
.detail-buy {
  background: var(--paper);
  border-radius: 10px;
  padding: 24px;
  margin-top: 25px;
}
.quantity {
  display: inline-flex;
  border: 1px solid var(--line);
  border-radius: 6px;
  overflow: hidden;
  background: white;
}
.quantity button {
  width: 36px;
  border: 0;
  background: white;
}
.quantity input {
  width: 65px;
  text-align: center;
  border: 0;
  padding: 10px 0;
}
.info-note {
  font-size: 11px;
  color: var(--muted);
  margin-top: 12px;
}
.card {
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 26px;
  background: white;
}
.panel {
  background: var(--paper);
  border-radius: 14px;
  padding: 30px;
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
  min-width: 0;
}
.field input,
.field select,
.field textarea,
.form-input {
  border: 1px solid var(--line);
  background: white;
  color: var(--ink);
  border-radius: 6px;
  min-height: 46px;
  padding: 10px 12px;
  width: 100%;
}
.field textarea {
  min-height: 110px;
  resize: vertical;
}
.field small {
  font-weight: 400;
  font-size: 11px;
  color: var(--muted);
}
.field-error {
  font-size: 11px;
  color: #9c3535;
}
.span-2 {
  grid-column: 1/-1;
}
.check-field {
  display: flex;
  align-items: start;
  gap: 10px;
  font-size: 12px;
  font-weight: 400;
}
.check-field input {
  margin-top: 4px;
  accent-color: var(--ink);
  width: 17px;
  height: 17px;
  flex-shrink: 0;
}
.auth-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 70px;
  max-width: 1000px;
  margin-inline: auto;
  align-items: start;
}
.auth-aside {
  padding: 40px;
  background: var(--paper);
  border-radius: 16px;
}
.auth-aside h2 {
  font-size: 32px;
}
.auth-aside p {
  margin-top: 20px;
  font-size: 13px;
}
.demo-accounts {
  margin-top: 24px;
  border-top: 1px solid var(--line);
  padding-top: 20px;
  display: grid;
  gap: 8px;
}
.demo-accounts button {
  border: 1px solid var(--line);
  background: white;
  border-radius: 6px;
  text-align: left;
  padding: 10px 14px;
  font-size: 11px;
}
.loading {
  padding: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--muted);
  font-size: 13px;
}
.spinner {
  width: 20px;
  height: 20px;
  border: 2px solid var(--line);
  border-top-color: var(--ink);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.error-box {
  background: #fff0ed;
  border: 1px solid #eecfc7;
  padding: 18px;
  border-radius: 8px;
  color: #873e30;
  font-size: 13px;
  margin-block: 15px;
}
.error-box button {
  margin-top: 12px;
}
.success-box {
  padding: 20px;
  border: 1px solid color-mix(in srgb, var(--lime) 45%, white);
  background: var(--lime-soft);
  border-radius: 10px;
}
.empty {
  text-align: center;
  padding: 60px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  color: var(--muted);
}
.empty h2 {
  font-size: 25px;
  color: var(--ink);
}
.toast {
  position: fixed;
  bottom: 25px;
  left: 50%;
  transform: translate(-50%, 30px);
  background: var(--ink);
  color: white;
  padding: 16px 25px;
  border-radius: 10px;
  z-index: 70;
  box-shadow: 0 6px 30px #1234;
  opacity: 0;
  pointer-events: none;
  max-width: calc(100vw - 30px);
  transition:
    opacity 0.2s,
    transform 0.2s;
}
.toast.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}
.modal {
  border: 0;
  border-radius: 14px;
  padding: 28px;
  color: var(--ink);
  width: min(620px, calc(100vw - 32px));
  max-height: 85dvh;
  overflow-y: auto;
  margin: auto;
  box-shadow: 0 20px 100px #0003;
}
html:has(.modal[open]) {
  overflow: hidden;
}
.modal::backdrop {
  background: #15323cb0;
  backdrop-filter: blur(3px);
}
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}
.modal-head h2 {
  font-size: 22px;
}
.mobile-nav {
  display: grid;
  gap: 10px;
}
.mobile-nav a,
.mobile-nav button {
  padding: 14px;
  min-height: 48px;
  font-size: 15px;
  border: 0;
  text-align: left;
  display: flex;
  gap: 10px;
}
.cart-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 350px;
  gap: 35px;
  align-items: start;
}
.cart-item {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 20px;
  border-bottom: 1px solid var(--line);
  padding-block: 24px;
}
.cart-item h3 {
  font-size: 15px;
  line-height: 1.5;
}
.cart-item p {
  font-size: 11px;
  margin-top: 8px;
  color: var(--muted);
}
.cart-item .row {
  margin-top: 12px;
}
.summary {
  background: var(--paper);
  border-radius: 12px;
  padding: 26px;
  position: sticky;
  top: 20px;
}
.summary h2 {
  font-size: 22px;
  margin-bottom: 20px;
}
.summary .total {
  font-size: 24px;
  border-top: 1px solid var(--line);
  padding-top: 20px;
  margin-top: 20px;
}
.summary .button {
  width: 100%;
  margin-top: 22px;
}
.orders-list {
  display: grid;
  gap: 18px;
}
.order-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 20px;
}
.table-wrap {
  overflow-x: auto;
  max-width: 100%;
}
table {
  border-collapse: collapse;
  width: 100%;
  font-size: 12px;
  text-align: left;
}
th,
td {
  padding: 15px 12px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}
th {
  font-size: 10px;
  color: var(--muted);
  font-weight: 650;
  letter-spacing: 0.04em;
}
td .button {
  white-space: nowrap;
}
.admin-tabs {
  display: flex;
  gap: 7px;
  overflow-x: auto;
  border-bottom: 1px solid var(--line);
  padding-bottom: 16px;
  margin-bottom: 28px;
}
.admin-tabs a {
  white-space: nowrap;
  padding: 9px 13px;
  font-size: 12px;
  border-radius: 6px;
}
.admin-tabs a.active {
  background: var(--ink);
  color: white;
}
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.stat strong {
  display: block;
  font-size: 35px;
  font-weight: 600;
  margin-top: 12px;
}
.stat span {
  font-size: 12px;
  color: var(--muted);
}
.admin-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}
.admin-cards .card h3 {
  font-size: 17px;
}
.admin-cards .card p {
  font-size: 12px;
  margin-top: 8px;
}
.admin-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 22px;
  flex-wrap: wrap;
}
.admin-toolbar h2 {
  font-size: 23px;
}
.admin-toolbar .form-input {
  max-width: 330px;
}
.order-meta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 14px 20px;
  margin-bottom: 22px;
  font-size: 13px;
}
.order-meta dt {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.order-meta dd {
  margin: 4px 0 0;
  overflow-wrap: anywhere;
}
.split-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
}
.prose {
  max-width: 720px;
}
.prose p {
  margin-top: 20px;
  color: var(--muted);
}
.directory-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.directory-grid .card {
  min-height: 150px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.directory-grid small {
  color: var(--muted);
}
.account-panels {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 30px;
}
.inline-search {
  max-width: 390px;
  display: flex;
  gap: 8px;
}
.inline-search input {
  min-width: 0;
}
.small-copy {
  font-size: 12px;
}
.modal form .actions {
  position: sticky;
  bottom: -28px;
  background: white;
  padding: 16px 0;
  margin-top: 16px;
}
.modal .form-grid {
  gap: 15px;
}
@media (min-width: 1500px) {
  .hero {
    min-height: 480px;
  }
  .hero-copy {
    padding: 60px;
  }
}
@media (max-width: 1100px) {
  .container {
    width: calc(100% - 48px);
  }
  .header-main {
    gap: 22px;
  }
  .search {
    margin-inline: 0;
  }
  .header-actions {
    gap: 12px;
  }
  .navline nav {
    gap: 24px;
  }
  .hero-copy {
    padding: 40px 32px;
  }
  .hero {
    min-height: 390px;
  }
  .catalog-layout {
    grid-template-columns: 180px minmax(0, 1fr);
    gap: 25px;
  }
  .catalog-layout .product-grid {
    gap: 16px;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
  .detail-grid {
    gap: 30px;
  }
  .cart-layout {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
  .auth-layout {
    gap: 35px;
  }
}
@media (max-width: 767px) {
  .container {
    width: calc(100% - 32px);
  }
  .section {
    padding-block: 38px;
  }
  .topbar {
    font-size: 9px;
  }
  .topbar .container > span {
    max-width: 220px;
  }
  .header-main {
    min-height: auto;
    display: grid;
    grid-template-columns: 34px 1fr auto;
    gap: 12px;
    padding-block: 18px;
  }
  .mobile-menu {
    display: inline-flex;
    margin-left: -10px;
  }
  .logo img {
    width: 143px;
  }
  .header-actions {
    gap: 4px;
  }
  .account-link span {
    display: none;
  }
  .account-link {
    padding: 10px;
  }
  .search {
    grid-column: 1/-1;
    grid-row: 2;
    margin-top: 7px;
    max-width: none;
    padding: 6px 12px;
  }
  .navline {
    display: none;
  }
  .demo-strip {
    font-size: 9px;
    gap: 10px;
    justify-content: space-between;
    padding-block: 3px;
  }
  .demo-strip span {
    max-width: 230px;
  }
  .needs {
    padding-top: 12px;
    padding-bottom: 15px;
  }
  .needs-intro {
    margin-bottom: 14px;
  }
  .needs-intro p {
    display: none;
  }
  .need-list {
    gap: 15px;
    justify-content: start;
    margin-right: -16px;
    padding-right: 16px;
  }
  .need {
    flex-basis: 76px;
    font-size: 10px;
    line-height: 1.35;
  }
  .need-circle {
    width: 70px;
    height: 70px;
  }
  .need-circle img {
    height: 57px;
    width: 55px;
  }
  .hero {
    grid-template-columns: 1fr;
    min-height: 0;
  }
  .hero-copy {
    padding: 32px 25px 30px;
  }
  .hero h1 {
    font-size: 38px;
    max-width: 340px;
  }
  .hero-copy > p:not(.eyebrow) {
    font-size: 12px;
    max-width: 290px;
  }
  .hero-visual {
    height: 235px;
  }
  .hero-visual img {
    object-position: center 50%;
  }
  .hero-caption {
    bottom: 12px;
    right: 12px;
    padding: 8px 12px;
  }
  .benefits {
    gap: 10px;
    padding-block: 20px;
  }
  .benefits > div {
    flex-direction: column;
    text-align: center;
    gap: 7px;
    font-size: 9px;
    line-height: 1.5;
  }
  .benefits strong {
    font-size: 10px;
  }
  .benefits svg {
    width: 20px;
    height: 20px;
  }
  .section-title {
    align-items: start;
    gap: 12px;
  }
  .section-title .text-link {
    font-size: 10px;
    white-space: nowrap;
    margin-top: 6px;
  }
  .section-title h2 {
    font-size: 25px;
  }
  .section-title .muted {
    font-size: 11px;
  }
  .line-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .line-card {
    min-height: 170px;
    padding: 24px;
  }
  .line-card img {
    width: 130px;
    height: 145px;
    right: 25px;
    top: 0;
  }
  .line-card h3 {
    font-size: 23px;
    max-width: 200px;
  }
  .line-card p {
    max-width: 170px;
    font-size: 10px;
  }
  .line-card .round-arrow {
    bottom: 16px;
    right: 15px;
  }
  .brand-strip {
    padding: 30px 0;
  }
  .brand-list {
    gap: 20px 30px;
    justify-content: center;
  }
  .brand-word {
    font-size: 22px;
  }
  .product-grid,
  .catalog-layout .product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 25px 14px;
  }
  .product-image {
    padding: 17px;
  }
  .product-card h3 {
    font-size: 11px;
    min-height: 50px;
  }
  .product-meta {
    font-size: 9px;
  }
  .product-bottom {
    font-size: 10px;
  }
  .product-bottom strong {
    font-size: 14px;
  }
  .product-bottom .icon-button {
    width: 28px;
    height: 28px;
  }
  .product-card .tag {
    font-size: 8px;
    left: 8px;
    top: 8px;
  }
  .cta-band {
    padding: 30px 24px;
    display: block;
  }
  .cta-band h2 {
    font-size: 28px;
  }
  .cta-band .button {
    margin-top: 25px;
  }
  .cta-band p {
    font-size: 12px;
  }
  .footer-grid {
    gap: 30px 20px;
    grid-template-columns: 1fr 1fr;
  }
  .footer-grid > div:first-child {
    grid-column: 1/-1;
  }
  .footer-grid > div:last-child {
    grid-column: 1/-1;
  }
  .footer-grid > div:first-child p {
    max-width: 240px;
  }
  .footer-bottom {
    font-size: 9px;
    gap: 15px;
  }
  .catalog-layout {
    display: block;
  }
  .filters {
    display: none;
  }
  .filter-trigger {
    display: inline-flex;
  }
  .catalog-toolbar {
    font-size: 11px;
    flex-wrap: wrap;
  }
  .inline-search {
    width: 100%;
    max-width: none;
  }
  .detail-grid {
    grid-template-columns: 1fr;
    gap: 26px;
  }
  .detail-image {
    padding: 30px;
    max-height: 380px;
  }
  .detail-info h1 {
    font-size: 28px;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .span-2 {
    grid-column: auto;
  }
  .auth-layout {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .auth-aside {
    padding: 26px;
    order: 2;
  }
  .auth-aside h2 {
    font-size: 26px;
  }
  .page-heading {
    margin-bottom: 25px;
  }
  .cart-layout {
    grid-template-columns: 1fr;
    gap: 26px;
  }
  .summary {
    position: static;
  }
  .cart-item {
    gap: 12px;
  }
  .cart-item h3 {
    font-size: 13px;
  }
  .card {
    padding: 20px;
  }
  .stats {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  .stat strong {
    font-size: 29px;
  }
  .admin-cards {
    grid-template-columns: 1fr;
  }
  .admin-tabs {
    margin-right: -16px;
    padding-right: 16px;
  }
  .split-content {
    grid-template-columns: 1fr;
    gap: 30px;
  }
  .directory-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  .account-panels {
    grid-template-columns: 1fr;
  }
  .table-wrap {
    margin-inline: -5px;
  }
  .modal {
    padding: 22px;
  }
  .modal-head h2 {
    font-size: 20px;
  }
  .modal form .actions {
    bottom: -22px;
  }
  .breadcrumbs {
    font-size: 10px;
    margin-bottom: 20px;
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

.hero-visual > img {
  object-position: 68% center;
}
.cta-band .button.secondary {
  background: var(--lime);
  color: var(--ink);
  border-color: var(--lime);
}
.cta-band .button.secondary:hover {
  background: #c4da30;
}
.need-list {
  scrollbar-width: none;
}
.need-list::-webkit-scrollbar {
  display: none;
}
